body:
{
  "pains": [
    {
      "id": "pain:verified-emails-bounce",
      "statement": "The list says verified, I send, and half of it bounces or the number rings the wrong business.",
      "element": "b2b:functional:product_quality",
      "shape": {
        "surface": "Emails marked deliverable come back as hard bounces, and phone numbers belong to someone else or nobody.",
        "operational": "They cross check the data by hand or in a second tool before every send, which is the work they paid the data vendor to skip.",
        "personal": null,
        "personal_note": "No source shows what the bounces cost the person (a flagged domain, a talk with a manager); the Trustpilot reviews for ZoomInfo and Apollo stop at the bounce rate and the refund fight."
      },
      "workflow": "Exporting a contact list from Apollo or ZoomInfo into the sequencer and sending, at the step where the first day's sends return as bounces and calls connect to the wrong company.",
      "type": "felt",
      "confidence": "high",
      "priority": 1,
      "felt_evidence": {
        "kind": "complaining",
        "what": "A dated September 2026 one star review of Apollo reports over 65% bounced and failed on a paid list.",
        "cites": ["src:3"]
      },
      "triggers": [],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {"situation": "when_it_bites", "verbatim": "Well over 65% bounce and failed rate.", "cites": ["src:3"]},
            {"situation": "venting", "verbatim": "Most contact numbers and emails are outdated and hardly any connection rates.", "cites": ["src:2"]},
            {"situation": "when_comparing", "verbatim": "Bounce rate is way higher that for other FREE platforms.", "cites": ["src:2"]},
            {"situation": "when_it_bites", "verbatim": "Most emails were non deliverable.", "cites": ["src:1"]},
            {"situation": "venting", "verbatim": "can mistake in data so we have cross check data for complete details", "cites": ["src:3"]},
            {"situation": "when_refusing", "verbatim": "the data quality was so poor that we decided not to move forward.", "cites": ["src:1"]}
          ],
          "costs_them": "The sends and dials they planned for the day, plus the hours spent re-checking every row before it goes out.",
          "fears": "No source shows the fear directly; the quotes stop at the bounce rate and the cross checking.",
          "dream_outcome": "A list they can send to as exported, with emails that land and numbers that reach the right business."
        }
      },
      "relief": {
        "line": "Send the list as it comes. The emails land and the numbers ring the right desk.",
        "says": [],
        "gap": "Read the Clay four and five star Trustpilot pages and the ZoomInfo and Apollo pages; none of the reviews fetched describes bounce rates after switching. G2 and Reddit, where switch stories live, refused the fetch."
      },
      "euphoria": {
        "line": "Trusted list. The reps stop checking the data and the domain stays clean all year.",
        "says": [],
        "gap": "No fetched review describes the year after fixing bounces; G2 and Reddit were blocked."
      },
      "segments": ["seg:lean"],
      "feature_ref": "feat:waterfall",
      "feature_note": "Running several providers in order and keeping the first verified hit is the direct answer to one vendor's stale record; whether Clay's waterfall lowers bounce rates in practice is unproven by any buyer source read here.",
      "cites": ["src:1", "src:2", "src:3"]
    },
    {
      "id": "pain:reading-linkedin-by-hand",
      "statement": "I spend my day reading prospects' LinkedIn posts by hand just to write one tailored opener.",
      "element": "b2b:ease_of_doing_business:time_savings",
      "shape": {
        "surface": "Each tailored message needs a pass through the prospect's LinkedIn posts and company before it can be written.",
        "operational": "Research is done manually row by row, which caps how many prospects a person can reach in a day.",
        "personal": null,
        "personal_note": "One reviewer says the tool that replaced manual operations work 'genuinely changed my life', which implies a personal cost, but no source states what the manual work cost them; left null."
      },
      "workflow": "Before writing a cold email in the sequencer, opening each prospect's LinkedIn profile and recent posts to find a line to personalise on, one prospect at a time.",
      "type": "felt",
      "confidence": "low",
      "priority": 2,
      "felt_evidence": {
        "kind": "paying",
        "what": "A September 2026 reviewer now pays for Clay to automate the LinkedIn post reading they used to do by hand.",
        "cites": ["src:7"]
      },
      "triggers": [],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {"situation": "when_it_bites", "verbatim": "I used to read through prospects' LinkedIn posts manually to craft tailored outbound messages.", "cites": ["src:7"]},
            {"situation": "venting", "verbatim": "As someone who used to do operations work manually", "cites": ["src:7"]},
            {"situation": "when_looking", "verbatim": "want to replace manual research with AI-driven automation", "cites": ["src:8"]}
          ],
          "costs_them": "Volume: the number of prospects they can personalise for is capped by how many profiles they can read.",
          "fears": "No source shows the fear; the quotes describe the manual work and stop.",
          "dream_outcome": "Tailored messages at the volume of untailored ones, without reading every profile."
        }
      },
      "relief": {
        "line": "Research runs itself. The same tailored outbound goes out at a far larger scale.",
        "says": [
          {"role": "end_user", "verbatim": "With this tool, I automate that process and run outbound at a significantly larger scale.", "cites": ["src:7"]}
        ],
        "gap": null
      },
      "euphoria": {
        "line": "A different job. The manual operator becomes the person who builds the system, and says it changed their life.",
        "says": [
          {"role": "end_user", "verbatim": "it has genuinely changed my life.", "cites": ["src:7"]}
        ],
        "gap": null
      },
      "segments": ["seg:lean", "seg:agency"],
      "feature_ref": "feat:claygents",
      "cites": ["src:7", "src:8"]
    },
    {
      "id": "pain:stuck-in-data-contract",
      "statement": "We're locked into a year-long data contract that auto-renewed on data we stopped trusting.",
      "element": "b2b:ease_of_doing_business:flexibility",
      "shape": {
        "surface": "A renewal or collections notice arrives for a data subscription the team no longer uses or trusts.",
        "operational": "They argue with the vendor's billing team, pay out the term, and buy a second source alongside it.",
        "personal": null,
        "personal_note": "No source shows the cost to the person who signed (budget owner's standing, explaining the spend); the reviews stop at the contract terms."
      },
      "workflow": "The annual ZoomInfo renewal date, at the step where the contract auto-renews without notice and the team discovers the exit window has passed.",
      "type": "felt",
      "confidence": "medium",
      "priority": 3,
      "felt_evidence": {
        "kind": "switching",
        "what": "An October 2026 one star ZoomInfo reviewer tells others to use Lusha, Clay or Apollo instead.",
        "cites": ["src:1"]
      },
      "triggers": [],
      "who_feels": ["economic_buyer"],
      "by_role": {
        "economic_buyer": {
          "says": [
            {"situation": "when_it_bites", "verbatim": "We are now stuck in a contract that does not reflect what we were told when we signed up", "cites": ["src:1"]},
            {"situation": "when_it_bites", "verbatim": "data was worthless and then they forced an auto renew without notification.", "cites": ["src:2"]},
            {"situation": "when_refusing", "verbatim": "Stick to the likes of Lusha, clay, Apollo!", "cites": ["src:1"]}
          ],
          "costs_them": "A year of budget committed to data they do not use or trust.",
          "fears": "No source states the fear; the quotes describe being stuck and the renewal.",
          "dream_outcome": "Paying for data only when they use it, and being free to leave."
        }
      },
      "relief": {
        "line": "Pay for what you pull. The data budget follows the campaigns, month to month.",
        "says": [],
        "gap": "Read the ZoomInfo Trustpilot pages and the Clay four and five star pages; one reviewer names alternatives, none describes life after leaving the contract. G2 switch reviews were blocked."
      },
      "euphoria": {
        "line": "Budget freedom. The team picks providers per job and nobody signs a seat contract again.",
        "says": [],
        "gap": "No fetched source describes the year after leaving an annual data contract."
      },
      "segments": ["seg:lean"],
      "feature_ref": "feat:waterfall",
      "feature_note": "Clay's waterfall bills per lookup across 200+ providers instead of one annual seat contract; that is the structural answer, but Clay's own credit model draws its own billing complaints (see pain:credits-burn-unpredictably).",
      "cites": ["src:1", "src:2"]
    },
    {
      "id": "pain:credits-burn-unpredictably",
      "statement": "Credits vanish on runs I never meant to start, and I can't tell what next month will cost.",
      "element": "b2b:ease_of_doing_business:transparency",
      "shape": {
        "surface": "The credit balance drops on runs nobody intended, or the account hits a limit while credits remain.",
        "operational": "They watch every run, test on a few rows first, and fight billing for refunds.",
        "personal": null,
        "personal_note": "No source shows the personal cost beyond money spent; the reviews name dollar amounts, not consequences for the person."
      },
      "workflow": "Running an enrichment or AI column in a Clay table (or exporting in Apollo), at the step where the run executes more rows or steps than intended and the credit balance drops.",
      "type": "felt",
      "confidence": "medium",
      "priority": 4,
      "felt_evidence": {
        "kind": "complaining",
        "what": "Dated 2026 one star reviews of both Clay and Apollo complain about credits consumed or blocked unexpectedly.",
        "cites": ["src:5", "src:4"]
      },
      "triggers": [],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {"situation": "when_it_bites", "verbatim": "they're stealing credit usage by running stuff that was never intended to run", "cites": ["src:5"]},
            {"situation": "venting", "verbatim": "everything is made to spend credit", "cites": ["src:6"]},
            {"situation": "venting", "verbatim": "Bugs and the flows you can't predict and understand which lead to more and more spendings.", "cites": ["src:6"]},
            {"situation": "when_it_bites", "verbatim": "for I am getting a limit, EVEN THOUGH I still have credits.", "cites": ["src:4"]}
          ],
          "costs_them": "Money they cannot forecast: one reviewer has spent multiple thousands on runs they could not predict.",
          "fears": "No source states the fear directly; the quotes stop at the spend.",
          "dream_outcome": "Knowing what a run will cost before it runs, and paying only for what they meant to run."
        }
      },
      "relief": {
        "line": "Spend you can see. Every run shows its price before it starts.",
        "says": [],
        "gap": "Read Clay's and Apollo's Trustpilot pages including the five star pages; no reviewer describes having credit spend under control."
      },
      "euphoria": {
        "line": "Predictable data budget. The ops person forecasts spend a quarter out and nobody asks about the bill.",
        "says": [],
        "gap": "No fetched source describes this."
      },
      "segments": ["seg:lean"],
      "feature_ref": null,
      "feature_note": "Clay is named in these complaints; no feature in brain/company addresses spend visibility. What would: a pre-run cost estimate, hard spend caps, or billing only on a returned result. This belongs in positioning's objections as much as in the offer.",
      "cites": ["src:5", "src:6", "src:4"]
    },
    {
      "id": "pain:too-hard-to-build",
      "statement": "It's so complicated I need a specialist just to build the table, and my salespeople can't use it.",
      "element": "b2b:ease_of_doing_business:simplification",
      "shape": {
        "surface": "The tool is hard to learn and the workflows are complicated for a simple lookup.",
        "operational": "Companies hire a dedicated GTM engineer or Clay specialist to design waterfalls and tune credit spend.",
        "personal": null,
        "personal_note": "No source shows the cost to the person; the reviews describe difficulty, not consequences."
      },
      "workflow": "Building a Clay table to find a contact's email or phone, at the step of setting up providers, waterfall order and AI prompts before the first row returns.",
      "type": "felt",
      "confidence": "medium",
      "priority": 5,
      "felt_evidence": {
        "kind": "hiring",
        "what": "A job posting hires a GTM engineer whose role is to design Clay waterfalls and tune provider order to cut wasted credits.",
        "cites": ["src:9"]
      },
      "triggers": [],
      "who_feels": ["end_user"],
      "by_role": {
        "end_user": {
          "says": [
            {"situation": "venting", "verbatim": "Extremely difficult to use, not intuitive at all.", "cites": ["src:5"]},
            {"situation": "venting", "verbatim": "the workflow is very complicated", "cites": ["src:5"]},
            {"situation": "when_refusing", "verbatim": "This is not built for speed and definately not to be used by salespeople.", "cites": ["src:6"]}
          ],
          "costs_them": "Time to learn before any result, or a salary for someone who already knows it.",
          "fears": "No source states the fear; the quotes stop at the difficulty.",
          "dream_outcome": "Getting from a list to enriched contacts without a specialist."
        }
      },
      "relief": {
        "line": "Past the basics. Once it clicks, the tool does far more than the old stack.",
        "says": [
          {"role": "end_user", "verbatim": "once you've figured out the basics, it's insanely powerful what this tool can do", "cites": ["src:7"]}
        ],
        "gap": null
      },
      "euphoria": {
        "line": "The superpower. The person who learned it becomes the team's GTM orchestrator.",
        "says": [
          {"role": "end_user", "verbatim": "Clay is my superpower of choice when it comes to GTM orchestration, visibility & business intelligence.", "cites": ["src:7"]}
        ],
        "gap": null
      },
      "segments": ["seg:lean"],
      "feature_ref": null,
      "feature_note": "Clay is the tool named as hard; no feature in brain/company addresses onboarding. What would: templates, done-for-you setup, or the agency segment as the operator. The specialist hiring is a sign the agency segment profits from this pain.",
      "cites": ["src:5", "src:6", "src:7"]
    }
  ],
  "awareness": {
    "default": {
      "level": "solution",
      "rationale": "Reviewers name and compare specific data tools (Lusha, Clay, Apollo, free platforms) and pay for them; they know solutions exist and are choosing between them.",
      "cites": ["src:1", "src:2"]
    }
  },
  "stats": [],
  "keywords": [
    "apollo verified emails bouncing",
    "zoominfo outdated data",
    "zoominfo auto renewal contract",
    "clay credits burned",
    "clay learning curve",
    "research prospects linkedin manually"
  ],
  "questions": [
    {
      "id": "q:pains-first-call",
      "question": "On the last ten first calls, which of these did the prospect name first: bounced data, manual research, a locked data contract, or something else?",
      "why": "Priority is ordered from public reviews; a customer's first sentence outranks all of them.",
      "would_change": "pains[].priority"
    },
    {
      "id": "q:pains-segment-attribution",
      "question": "Which segment do your customers who complain about bounced lists and ZoomInfo contracts sit in: agencies, lean in-house teams, or RevOps?",
      "why": "Trustpilot reviewers rarely state company size or role, so segments were inferred from tone and price points.",
      "would_change": "pains[].segments"
    },
    {
      "id": "q:pains-stitching-tools",
      "question": "Do customers say they used to stitch many tools together before Clay? One agency reviewer said so; nobody else did in what we read.",
      "why": "Found once (src:8), not twice, so it is not a row; it maps to feat:workflows.",
      "would_change": "pains[]"
    },
    {
      "id": "q:pains-revops",
      "question": "What do RevOps buyers at scale say hurts: CRM hygiene, data decay, or provider sprawl?",
      "why": "The RevOps segment was not reached; Reddit, G2 and LinkedIn posts were blocked and Trustpilot reviewers skew small.",
      "would_change": "pains[].segments, awareness"
    },
    {
      "id": "q:pains-personal",
      "question": "When a list bounces or a contract renews, what happens to the person who owned it?",
      "why": "Every personal rung is null; no public source showed it.",
      "would_change": "pains[].shape.personal"
    }
  ],
  "sources": [
    {
      "id": "src:1",
      "url": "https://www.trustpilot.com/review/zoominfo.com",
      "title": "ZoomInfo reviews",
      "venue": "Trustpilot, independent review site; excerpts from several reviewers",
